  toCsv: (
    rows: readonly Readonly<
      Record<string, string | number | boolean | null>
    >[],
    columns: readonly string[],
  ): string =>
    [
      columns.join(","),
      ...rows.map((row) =>
        columns.map((column) => csvModule.escapeCsvValue(row[column] ?? null)).join(","),
