type BucketState = { tokens: number; capacity: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/**
 * Plan hints for orgs the database does not know about. An org that exists is
 * always sized from its subscription, so a stale hint can never outlive a plan
 * change.
 */
const planByOrg = new Map<OrgId, PlanId>();

/** Records the plan to size buckets by for an org that has no stored record. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

/**
 * The plan that sizes `orgId`'s buckets: the org's current plan when it can be
 * read, otherwise a recorded hint, otherwise free (anonymous callers such as
 * login and password reset have no org at all).
 */
async function resolvePlan(orgId: OrgId): Promise<PlanId> {
  try {
    const org = await findOrgById(orgId);
    if (org !== null) return org.plan;
  } catch {
    // No readable store: fall through to the hint rather than failing the request.
  }
  return planByOrg.get(orgId) ?? "free";
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

