/**
 * The subscription is the single authority on a workspace's plan: everything
 * that depends on the plan has to follow it the moment it changes, including
 * for workspaces whose organization row already disagrees.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { getDb, organizations, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as activityService from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { PlanId } from "@/types/billing";

let cleanup: () => void;

const NOW = new Date("2026-06-01T07:00:00.000Z");
const PAST = toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z"));

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

function projectInput(tenant: Tenant, n: number) {
  return {
    orgId: tenant.org.id,
    name: `Extra ${n}`,
    slug: "",
    key: `X${n}${n}`,
    description: null,
    visibility: "org" as const,
    leadId: tenant.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  };
}

function expireTrial(tenant: Tenant): void {
  getDb()
    .update(subscriptions)
    .set({ currentPeriodEnd: PAST })
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
}

async function planOf(tenant: Tenant): Promise<PlanId> {
  const org = await orgRepo.findOrgById(tenant.org.id);
  return org!.plan;
}

describe("an upgrade takes effect everywhere", () => {
  it("lifts quotas, features, the displayed plan and the burst limits", async () => {
    const tenant = await createTenant("upgrade", "free");

    // Fixture: one project already exists, free allows two.
    await projectService.createProject(tenant.actors.owner, projectInput(tenant, 1));
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(tenant, 2)),
    ).rejects.toThrow(/allows/);

    await expect(
      activityService.exportActivity(tenant.actors.owner, {
        orgId: tenant.org.id,
        since: null,
        until: null,
        format: "csv",
      } as never),
    ).rejects.toThrow(/not included/);

    const before = await consumeRateLimit(tenant.org.id, "comment:create");

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(await planOf(tenant)).toBe("growth");
    expect((await orgRepo.findOrgBySlug("upgrade"))!.plan).toBe("growth");
    expect(
      (await orgRepo.listOrgsForUser(tenant.userIds.owner)).map((o) => o.plan),
    ).toEqual(["growth"]);

    await projectService.createProject(tenant.actors.owner, projectInput(tenant, 3));

    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "fifth@upgrade.test",
        role: "member",
      }),
    ).resolves.toBeDefined();

    await expect(
      activityService.exportActivity(tenant.actors.owner, {
        orgId: tenant.org.id,
        since: null,
        until: null,
        format: "csv",
      } as never),
    ).resolves.toEqual(expect.any(String));

    let allowed = 0;
    for (let i = 0; i < 200; i += 1) {
      if ((await consumeRateLimit(tenant.org.id, "comment:create")).allowed) allowed += 1;
    }
    expect(before.remaining).toBe(59);
    expect(allowed).toBe(200);
  });

  it("follows a downgrade: webhooks are refused after moving to starter", async () => {
    const tenant = await createTenant("downgrade", "growth");

    await expect(
      webhookService.createWebhook(tenant.actors.admin, {
        orgId: tenant.org.id,
        url: "https://example.test/hook",
        events: ["issue.created"],
      } as never),
    ).resolves.toBeDefined();

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    // Starter has two endpoints' worth of quota, but not the webhooks feature.
    // Wait: the existing endpoint still fits, so the change is accepted.
    expect(await planOf(tenant)).toBe("starter");

    await expect(
      webhookService.createWebhook(tenant.actors.admin, {
        orgId: tenant.org.id,
        url: "https://example.test/hook-2",
        events: ["issue.created"],
      } as never),
    ).rejects.toThrow(/not included/);
  });

  it("re-bases a spent bucket on the new capacity", async () => {
    const tenant = await createTenant("bucket", "free");
    for (let i = 0; i < 60; i += 1) {
      expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(true);
    }
    expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(false);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect((await consumeRateLimit(tenant.org.id, "comment:create")).allowed).toBe(true);
  });
});

describe("workspaces whose records already disagree", () => {
  it("uses the subscription's plan over the organization row", async () => {
    const tenant = await createTenant("stale", "free");
    getDb()
      .update(subscriptions)
      .set({ plan: "growth" })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();

    expect(await planOf(tenant)).toBe("growth");
    await projectService.createProject(tenant.actors.owner, projectInput(tenant, 1));
    await projectService.createProject(tenant.actors.owner, projectInput(tenant, 2));
  });

  it("uses the organization row when there is no subscription", async () => {
    const tenant = await createTenant("bare", "free");
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).run();
    getDb()
      .update(organizations)
      .set({ plan: "starter" })
      .where(eq(organizations.id, tenant.org.id))
      .run();

    expect(await planOf(tenant)).toBe("starter");
    expect((await billingService.checkLimit(tenant.org.id, "seats", 0)).plan).toBe("starter");
  });

  it("never lets one workspace's plan leak into another", async () => {
    const a = await createTenant("iso-a", "free");
    const b = await createTenant("iso-b", "free");
    await billingService.changePlan(a.actors.owner, {
      orgId: a.org.id,
      plan: "growth",
      interval: "monthly",
    });
    expect(await planOf(a)).toBe("growth");
    expect(await planOf(b)).toBe("free");
  });
});

describe("trial expiry", () => {
  it("moves an expired trial to free and every reader follows", async () => {
    const tenant = await createTenant("trial-over", "growth");
    expireTrial(tenant);

    const result = await runTrialExpiryJob(NOW);
    expect(result.processed).toBeGreaterThanOrEqual(1);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription!.plan).toBe("free");
    expect(await planOf(tenant)).toBe("free");

    await projectService.createProject(tenant.actors.owner, projectInput(tenant, 1));
    await expect(
      projectService.createProject(tenant.actors.owner, projectInput(tenant, 2)),
    ).rejects.toThrow(/allows/);
  });

  it("leaves a workspace that chose a paid plan during its trial alone", async () => {
    const tenant = await createTenant("trial-chosen", "growth");
    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    expireTrial(tenant);

    await runTrialExpiryJob(NOW);
    expect(await planOf(tenant)).toBe("starter");
  });

  it("is idempotent", async () => {
    const tenant = await createTenant("trial-twice", "growth");
    expireTrial(tenant);

    await runTrialExpiryJob(NOW);
    const first = await subscriptionRepo.findSubscription(tenant.org.id);
    const second = await runTrialExpiryJob(NOW);
    const after = await subscriptionRepo.findSubscription(tenant.org.id);

    expect(second.processed).toBe(0);
    expect(after).toEqual(first);
  });
});

